with filtered_departments as (select * from departments where not (dept_name = 'Legal' and location = 'Bangkok' and budget between 1354000 and 3876000)), budget_bucket_summary as (select case when budget >= 3756000 then 'high' when budget >= 1268000 then 'mid' else 'low' end as budget_bucket, count(budget) as budget_count from filtered_departments group by case when budget >= 3756000 then 'high' when budget >= 1268000 then 'mid' else 'low' end) select budget_bucket, budget_count from budget_bucket_summary where budget_count > 8;
